#include <cstdint>
#include <array>
#include <stdexcept>

class RingKV {
    static constexpr size_t CAP = 1024;
    std::array<int64_t, CAP> buf{};
    size_t head = 0, tail = 0, sz = 0;

public:
    void push(int64_t id) {
        if (sz == CAP) throw std::overflow_error("RingKV full");
        buf[tail] = id;
        tail = (tail + 1) % CAP;
        ++sz;
    }

    int64_t pop() {
        if (sz == 0) throw std::underflow_error("RingKV empty");
        int64_t v = buf[head];
        head = (head + 1) % CAP;
        --sz;
        return v;
    }

    size_t size() const { return sz; }
};
